output-contract.example:
{
  "artefact_id": "gobe-example-001",
  "owner": "alex@acme.com",
  "decision": "see templates/go-backend.md for shape",
  "rationale": "Decision cites input artefact A (URL) and input artefact B (path). The rationale is at least two sentences and identifies which constraints drove the call.",
  "inputs_used": [
    {
      "name": "A",
      "source": "https://example.com/A"
    },
    {
      "name": "B",
      "source": "repo:path/B"
    }
  ],
  "version": "1.0.0",
  "last_reviewed": "2026-05-23"
}

section.code:
{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "$id": "https://faion.net/schemas/go-backend-tree",
  "type": "object",
  "required": ["modulePath", "entry", "internalDirs"],
  "properties": {
    "modulePath": {"type": "string", "pattern": "^[a-z0-9./_-]+$"},
    "entry": {"const": "cmd/api/main.go"},
    "internalDirs": {
      "type": "array",
      "items": {"enum": ["handler", "service", "repository", "model", "middleware", "config"]},
      "minItems": 5,
      "uniqueItems": true
    },
    "externalInternalImports": {
      "type": "array",
      "description": "Must be empty: no file outside the module may import the module's internal/ packages.",
      "maxItems": 0
    },
    "forbiddenPatterns": {
      "type": "array",
      "items": {"enum": [
        "c.JSON(http.Status",
        "go func() { ... c.Request",
        "BindJSON(",
        "interface { } in repository/"
      ]}
    }
  }
}

example.code:
// internal/handler/user.go — REJECTED
func (h *UserHandler) Create(c *gin.Context) {
    var u model.User                          // direct domain bind (r-request-dto violated)
    if err := c.BindJSON(&u); err != nil {     // BindJSON aborts (r-shouldbind-json violated)
        c.JSON(400, gin.H{"error": err})       // direct JSON (r-central-error-middleware violated)
        return
    }
    go func() { h.s.Process(c) }()             // c captured in goroutine (r-context-propagation violated)
}
